//----------------------------------------------------------------------------------------// TPingDocument constructor //----------------------------------------------------------------------------------------TPingDocument::TPingDocument(TFile* itsFile, OSType itsCreator) :	TFileBasedDocument(itsFile, itsCreator),	fPingThreadRunner(),	fLog(NULL){}//----------------------------------------------------------------------------------------// TPingDocument destructor//----------------------------------------------------------------------------------------TPingDocument::~TPingDocument(){}//----------------------------------------------------------------------------------------// TPingDocument::Changed//----------------------------------------------------------------------------------------void TPingDocument::Changed(ChangeID_AC theChange, void* changeData) // override{	TFileBasedDocument::Changed(theChange, changeData);	if (theChange == mClosed)	{		if (fPingThreadRunner)		{			if (fLog.GetView())				fLog << "Canceling" << endl_AC;			fPingThreadRunner->Join();		}		fLog.Flush();		fLog.SetView(NULL);	}	else if (theChange == cPing)		fPingThreadRunner = NULL;}//----------------------------------------------------------------------------------------// TPingDocument::DoMakeViews://----------------------------------------------------------------------------------------void TPingDocument::DoMakeViews(bool /*forPrinting*/) // override {	TWindow* aWindow = gViewServer->NewTemplateWindow(kPingWindowID, this);	::ThrowIfNULL_AC(aWindow);	TView* mainView = aWindow->FindSubView('TeVW');	if (mainView)	{		TH_new TStdPrintHandler(this, mainView, kFixedSize, kFixedSize);				TWEView* theWEView = dynamic_cast_AC(TWEView*, mainView);		if (theWEView)			fLog.SetView(theWEView);	}}//----------------------------------------------------------------------------------------// TPingDocument::DoPing://----------------------------------------------------------------------------------------void TPingDocument::DoPing(const CStr255_AC& hostName){	SetTitle(CString_AC(hostName));	CInetAddress inetAddress(hostName);	TPingClient* pingClient = TH_new TPingClient(inetAddress.fHost, fLog);	TThreadCommand* pingCommand = TH_new TThreadCommand(cPing, pingClient, this, this);	PostCommand(pingCommand);	fPingThreadRunner = pingClient;}//----------------------------------------------------------------------------------------// End of UPingDocument.cpp